#!/usr/bin/env python3
"""SCRIPT GENERATED BY CLAUDE"""

"""Basic curses chat TUI.

Layout:
    +----------------------------+-------------+
    |  chat history              | penguin     |
    |                            | [ button ]  |
    +----------------------------+-------------+
    | text entry (2 lines, full width)         |
    +------------------------------------------+
"""
import curses
from comm import TCPClient
import textwrap
import time
import sys

PENGUIN_W = 36           # columns the penguin needs inside the right box
PENGUIN_H = 16           # rows the penguin needs
BUTTON_H = 3
MIN_H = PENGUIN_H + BUTTON_H + 2 + 4 + 1   # penguin + button + borders + input box
FLASH_SECS = 0.15        # minimum time the button stays highlighted after a click
PROMPT = "> "
PROMPT_W = len(PROMPT)
INPUT_H = 4              # 2 text lines + top/bottom border


# ---------------------------------------------------------------------------
# Rules panel (shown under the penguin). To add a rule, add one string to RULES.
#   - Each string becomes one "> " bullet and is word-wrapped automatically.
#   - Use "\n" inside a string for an indented follow-up line (like the e.g. below).
# ---------------------------------------------------------------------------
WELCOME = "Welcome to OS Trivia!"
RULES_TITLE = "Rules:"
RULES = [
    "Press BUZZER! to buzz in when you know the answer.",
    "One attempt per question.",
    "Correct Answers: +1 pt.",
    "You can chat with other players!",
    "Scroll chat with mouse wheel or PageUP/PageDOWN.",
    "Press ESC to disconnect.",
]
BULLET = "> "

def build_rules_lines(width):
    """Return [(text, is_header), ...] for the rules panel, wrapped to `width`."""
    lines = [(WELCOME, True), (RULES_TITLE, True)]
    indent = " " * len(BULLET)
    for rule in RULES:
        first, *notes = rule.split("\n")
        for l in textwrap.wrap(first, width, initial_indent=BULLET, subsequent_indent=indent):
            lines.append((l, False))
        for note in notes:
            for l in textwrap.wrap(note, width, initial_indent=indent, subsequent_indent=indent):
                lines.append((l, False))
    return lines


# ---------------------------------------------------------------------------
# Hooks: put your own logic here
# ---------------------------------------------------------------------------
def on_button_click(app):
    """Called whenever the button is clicked."""
    client.send({"action": "buzz"})

def on_message_submit(app, text):
    """Called whenever the user presses Enter in the text box."""
    client.send({"action": "text_input", "text": text})


# ---------------------------------------------------------------------------
# Penguin (your functions; x positions made relative to base_x so it can be
# placed anywhere)
# ---------------------------------------------------------------------------
def seg(stdscr, y, x, text, attr):
    """Draw one colored segment and return the x position right after it."""
    try:
        stdscr.addstr(y, x, text, attr)
    except curses.error:
        pass  # off-screen writes (e.g. bottom-right corner) are expected; ignore
    return x + len(text)


# https://www.asciiart.eu/art/5e6e97e0bd18eee0, ASCII art by Harry Mason (Hajoma)
def draw_penguin(stdscr, base_x, base_y, BLUE_BLACK, WHITE_BLACK, GREEN_BLACK, YELLOW_BLACK):
    seg(stdscr, base_y + 0, base_x, "     _nnnn_                      ", BLUE_BLACK)
    x = seg(stdscr, base_y + 1, base_x, "    dGGGGMMb", BLUE_BLACK)
    x = seg(stdscr, base_y + 2, base_x, "   @p~qp~~qMb", BLUE_BLACK)

    seg(stdscr, base_y + 1, base_x + 12, "    ,..............", WHITE_BLACK)
    seg(stdscr, base_y + 2, base_x + 16, "|", WHITE_BLACK)
    seg(stdscr, base_y + 2, base_x + 18, "OS Trivia!", WHITE_BLACK | curses.A_BLINK)
    seg(stdscr, base_y + 2, base_x + 31, "|", WHITE_BLACK)
    seg(stdscr, base_y + 3, base_x + 12, "   _;..............'", WHITE_BLACK)

    x = seg(stdscr, base_y + 3, base_x, "   M", BLUE_BLACK)
    x = seg(stdscr, base_y + 3, x, " (", WHITE_BLACK)
    x = seg(stdscr, base_y + 3, x, "@", GREEN_BLACK)
    x = seg(stdscr, base_y + 3, x, "||", WHITE_BLACK)
    x = seg(stdscr, base_y + 3, x, "@", GREEN_BLACK)
    x = seg(stdscr, base_y + 3, x, ")", WHITE_BLACK)
    x = seg(stdscr, base_y + 3, x, "M|", BLUE_BLACK)

    seg(stdscr, base_y + 4, base_x, "   @", BLUE_BLACK)
    x = seg(stdscr, base_y + 4, base_x + 4, ",----.", YELLOW_BLACK)
    x = seg(stdscr, base_y + 4, x, "JM|", BLUE_BLACK)
    seg(stdscr, base_y + 4, x, " -'", WHITE_BLACK)

    x = seg(stdscr, base_y + 5, base_x, "  S^", BLUE_BLACK)
    x = seg(stdscr, base_y + 5, x, "\\___/", YELLOW_BLACK)
    seg(stdscr, base_y + 5, x, " qKL", BLUE_BLACK)

    seg(stdscr, base_y + 6, base_x, " dZP        qKRb", BLUE_BLACK)
    seg(stdscr, base_y + 7, base_x, "dZP          qKKb", BLUE_BLACK)
    seg(stdscr, base_y + 8, base_x, "fZP            SMMb", BLUE_BLACK)
    seg(stdscr, base_y + 9, base_x, "HZM            MMMM", BLUE_BLACK)
    seg(stdscr, base_y + 10, base_x, "FqM            MMMM", BLUE_BLACK)

    x = seg(stdscr, base_y + 11, base_x, '__| ".        |\\', YELLOW_BLACK)
    seg(stdscr, base_y + 11, x, 'dS"qML', BLUE_BLACK)

    x = seg(stdscr, base_y + 12, base_x, "|    `.       | `' \\", YELLOW_BLACK)
    seg(stdscr, base_y + 12, x, "Zq", BLUE_BLACK)

    x = seg(stdscr, base_y + 13, base_x - 1, "_)      \\", YELLOW_BLACK)
    x = seg(stdscr, base_y + 13, x, ".___.,", BLUE_BLACK)
    seg(stdscr, base_y + 13, x, "|     .'", YELLOW_BLACK)

    x = seg(stdscr, base_y + 14, base_x - 1, "\\____   )", YELLOW_BLACK)
    x = seg(stdscr, base_y + 14, x, "MMMMMM", BLUE_BLACK)
    seg(stdscr, base_y + 14, x, "|   .'", YELLOW_BLACK)

    seg(stdscr, base_y + 15, base_x, "    `-'       `--'", YELLOW_BLACK)


# ---------------------------------------------------------------------------
# App
# ---------------------------------------------------------------------------
class ChatApp:
    def __init__(self, stdscr):
        self.stdscr = stdscr
        self.history = []        # list of (sender, text)
        self.buffer = ""
        self.scroll_offset = 0
        self.button_pressed = False
        self.flash_until = 0.0
        self.too_small = False

        curses.curs_set(1)
        curses.start_color()
        curses.init_pair(1, curses.COLOR_WHITE, curses.COLOR_BLACK)
        curses.init_pair(2, curses.COLOR_BLUE, curses.COLOR_BLACK)
        curses.init_pair(3, curses.COLOR_GREEN, curses.COLOR_BLACK)
        curses.init_pair(4, curses.COLOR_YELLOW, curses.COLOR_BLACK)
        curses.init_pair(5, curses.COLOR_RED, curses.COLOR_BLACK)
        self.WHITE = curses.color_pair(1)
        self.BLUE = curses.color_pair(2) | curses.A_BOLD
        self.GREEN = curses.color_pair(3)
        self.YELLOW = curses.color_pair(4)
        self.RED = curses.color_pair(5)
        stdscr.bkgd(" ", self.WHITE)

        curses.mousemask(curses.ALL_MOUSE_EVENTS)
        curses.mouseinterval(0)   # report press/release immediately (no click-merging delay)
        self.build_windows()

    # -- layout -------------------------------------------------------------
    def build_windows(self):
        H, W = self.stdscr.getmaxyx()
        right_w = max(W // 4, PENGUIN_W + 2)
        if H < MIN_H or W < right_w + 20:
            self.too_small = True
            self.input_win = self.stdscr
            return
        self.too_small = False

        top_h = H - INPUT_H
        self.right_x = W - right_w                     # screen column where the side pane starts
        self.chat = curses.newwin(top_h, W - right_w, 0, 0)
        self.right = curses.newwin(top_h, right_w, 0, self.right_x)
        self.input_win = curses.newwin(INPUT_H, W, top_h, 0)
        for w in (self.right, self.chat, self.input_win):
            w.bkgd(" ", self.WHITE)
        self.input_win.keypad(True)

        # button geometry (screen coordinates) for hit testing
        self.btn_h = BUTTON_H
        self.btn_w = right_w - 4
        self.btn_y = top_h - BUTTON_H - 1
        self.btn_x = 2

    # -- state --------------------------------------------------------------
    def add_message(self, sender, text):
        self.history.append((sender, text))

    # -- drawing ------------------------------------------------------------
    def draw(self):
        self.stdscr.erase()
        if self.too_small:
            msg = f"Terminal too small (need at least {MIN_H} rows)"
            try:
                self.stdscr.addstr(0, 0, msg[: self.stdscr.getmaxyx()[1] - 1])
            except curses.error:
                pass
            self.stdscr.refresh()
            return

        self.draw_title()
        self.draw_chat()
        self.draw_input()   # last, so the cursor ends up in the input box

    def draw_title(self):
        # Set the proper dimensions
        w = self.right
        w.erase()
        w.attrset(self.WHITE)
        w.box()
        draw_penguin(w, 2, 1, self.BLUE, self.WHITE, self.GREEN, self.YELLOW)

        self.draw_rules(w)

        # button: simple outline, inverted while pressed
        label = "BUZZER!"
        lit = self.button_pressed or time.monotonic() < self.flash_until
        attr = self.RED | curses.A_BOLD | (curses.A_REVERSE if lit else 0)
        by, bx, bw = self.btn_y, self.btn_x, self.btn_w
        try:
            w.addstr(by, bx, "+" + "-" * (bw - 2) + "+", self.RED | curses.A_BOLD)
            w.addstr(by + 1, bx, "|" + label.center(bw - 2) + "|", attr)
            w.addstr(by + 2, bx, "+" + "-" * (bw - 2) + "+", self.RED | curses.A_BOLD)
        except curses.error:
            pass
        w.noutrefresh()

    def draw_rules(self, w):
        """Draw the rules between the penguin and the button, clipping if short on space."""
        top = 1 + PENGUIN_H + 1                  # first row under the penguin
        bottom = self.btn_y - 1                  # last usable row (leave a gap above button)
        avail = bottom - top + 1
        if avail <= 0:
            return
        width = w.getmaxyx()[1] - 4
        lines = build_rules_lines(width)
        if len(lines) > avail:                   # not enough rows: truncate and mark it
            lines = lines[:avail - 1] + [("...", False)]
        for i, (text, header) in enumerate(lines):
            try:
                w.addstr(top + i, 2, text, self.WHITE | (curses.A_BOLD if header else 0))
            except curses.error:
                pass

    def draw_chat(self):
        # Set the proper dimensions
        w = self.chat
        w.erase()
        w.attrset(self.WHITE)
        w.box()
        h, width = w.getmaxyx()
        inner_w, inner_h = width - 2, h - 2

        # Wrap lines around window borders
        lines = []
        wrapped = []
        for sender, text in self.history:
            wrapped = textwrap.wrap(f"{text}", inner_w) or [""]
            # Add sender back to newly wrapped text
            for line in wrapped:
                lines.append((sender, line))

        # Clamp scroll offset to valid bounds
        max_scroll = max(0, len(lines) - inner_h)
        self.scroll_offset = max(0, min(self.scroll_offset, max_scroll))

        # Calculate which lines to display based on the offset
        if self.scroll_offset == 0:
            visible_lines = lines[-inner_h:] if inner_h <= len(lines) else lines
        else:
            end = len(lines) - self.scroll_offset
            start = max(0, end - inner_h)
            visible_lines = lines[start:end]

        # Unwrap lines and add them to log
        for i, (sender, line) in enumerate(visible_lines[-inner_h:]):
            try:
                # Different color lines depending on sender
                if (sender == 'SERVER'):
                    w.addstr(1 + i, 1, line, self.GREEN)
                elif (sender == 'BUZZER'):
                    w.addstr(1 + i, 1, line, self.RED)
                else:
                    w.addstr(1 + i, 1, line, self.WHITE)
            except curses.error:
                pass
        w.noutrefresh()

    def draw_input(self):
        # Set the proper dimensions
        w = self.input_win
        w.erase()
        w.attrset(self.WHITE)
        w.box()
        inner_w = w.getmaxyx()[1] - 2 - PROMPT_W

        chunks = [self.buffer[i:i + inner_w] for i in range(0, len(self.buffer), inner_w)] or [""]
        if self.buffer and len(self.buffer) % inner_w == 0:
            chunks.append("")
        visible = chunks[-2:]
        first_idx = len(chunks) - len(visible)
        for i, line in enumerate(visible):
            try:
                if first_idx + i == 0:          # prompt only on the first line of the message
                    w.addstr(1 + i, 1, PROMPT, curses.A_BOLD)
                w.addstr(1 + i, 1 + PROMPT_W, line)
            except curses.error:
                pass
        w.move(len(visible), 1 + PROMPT_W + len(visible[-1]))
        w.noutrefresh()
        curses.doupdate()

    # -- input --------------------------------------------------------------
    def handle_mouse(self):
        try:
            _, mx, my, _, bstate = curses.getmouse()
        except curses.error:
            return
        if self.too_small:
            return

        # Pick up scroll wheel input
        NUM_UP = 65536
        NUM_DOWN = 2097152
        # Mouse Wheel Up
        if bstate == NUM_UP:
            self.scroll_offset += 3
            return
        # Mouse Wheel Down
        if bstate == NUM_DOWN:
            self.scroll_offset -= 3
            return

        # btn_x is relative to the side pane; mouse coordinates are screen-wide
        screen_btn_x = self.right_x + self.btn_x
        inside = (self.btn_y <= my < self.btn_y + self.btn_h and
                  screen_btn_x <= mx < screen_btn_x + self.btn_w)
        if bstate & curses.BUTTON1_PRESSED:
            self.button_pressed = inside
            if inside:      # light up the moment the mouse goes down
                self.flash_until = time.monotonic() + FLASH_SECS
        elif bstate & (curses.BUTTON1_CLICKED | curses.BUTTON1_RELEASED):
            self.button_pressed = False
            if inside:
                # CLICKED-only terminals never send PRESSED, so flash here too
                self.flash_until = max(self.flash_until, time.monotonic() + FLASH_SECS / 2)
                on_button_click(self)

    def run(self):
        while True:
            # Poll for server messages
            messages = client.recv_all()
            for msg in messages:
                # Recieve broadcasted server messages
                text = msg.get("msg")
                if text:
                    if "buzzed in!" in text:
                        self.add_message("BUZZER", text)
                    elif text.startswith("[") and "]:" in text:
                        self.add_message("PLAYER", text)
                    else:
                        self.add_message("SERVER", text)
                    
                # Graceful exit on disconnect
                if msg.get("action") == "server_disconnect":
                    self.add_message("PLAYER", "Disconecting . . .")
                    return

            # Update screen
            self.draw()

            # While the button is flashing, wake up regularly so it un-highlights on time
            remaining = self.flash_until - time.monotonic()
            timeout_ms = max(1, int(remaining * 1000) + 5) if remaining > 0 else 100
            self.input_win.timeout(timeout_ms)

            # Get user's keypresses, continue loop if no input
            ch = self.input_win.getch()
            if ch == -1:
                continue

            if ch == curses.KEY_RESIZE:                 # Rebuild windows on resize window event
                curses.update_lines_cols()
                self.build_windows()
            elif ch == curses.KEY_MOUSE:                # Handle mouse clicks
                self.handle_mouse()
            elif ch == curses.KEY_PPAGE:                # Page Up to scroll chat
                self.scroll_offset += 10
            elif ch == curses.KEY_NPAGE:                # Page Down key to scroll chat
                self.scroll_offset -= 10
            elif ch in (curses.KEY_ENTER, 10, 13):      # Send messages upon hitting ENTER/RETURN
                text = self.buffer.strip()
                self.buffer = ""
                self.scroll_offset = 0                  # Snap scroll to present message
                if text:
                    on_message_submit(self, text)
            elif ch in (curses.KEY_BACKSPACE, 127, 8):  # Delete char from input buffer
                self.buffer = self.buffer[:-1]
            elif ch == 27:                              # Esc quits
                break
            elif 32 <= ch <= 126:                       # All other keys serve as valid keypresses to be sent to chat
                self.buffer += chr(ch)


def main(stdscr):
    # Run the TUI
    ChatApp(stdscr).run()


if __name__ == "__main__":
    # Get the proxy address (changes upon ngrok resetting) and username
    get_input = input("Enter username (max 15 chars): ")
    username = get_input[:15]

    while True:
        address = input("Enter ngrok address/port: ")

        try:
            # Catch formatting errors (missing colon, letters instead of port numbers)
            host, port = address.strip().split(":")
            port = int(port) 
            
            print(f"Attempting to connect to {host} on port {port}...")
            
            # Catch actual networking errors during connection
            client = TCPClient(host, port)
            
            # If we reach this line, connection succeeded. Break the loop.
            break 
            
        except ValueError:
            print("[Error] Invalid format. Make sure you include the colon (e.g., address:port).")
        except socket.gaierror:
            print("[Error] Could not resolve address. Check for typos in the ngrok URL.")
        except ConnectionRefusedError:
            print("[Error] Connection refused. The server might be down or restarting.")
        except TimeoutError:
            print("[Error] Connection timed out. Check your internet connection.")
        except Exception as e:
            print(f"[Error] Unexpected failure: {e}")

    
    client.send({"action": "join", "username": username})
    curses.wrapper(main)
    print("\nConnection closed. Thanks for playing!\n")